#!/usr/bin/env python3
# بخش «نسل‌کشی هزاره‌ها در تاریخ»: اصلاح مدخل‌های موجود بر پایه‌ی منابع، و افزودن
# رویدادهای مستندِ جاافتاده. ورودی: ../sections/genocide.json (محتوای پیشین)؛ خروجی همان فایل.
import json, os
here = os.path.dirname(os.path.abspath(__file__))
path = os.path.join(here, "..", "sections", "genocide.json")
rows = json.load(open(os.path.join(here, "genocide_base.json"), encoding="utf-8"))  # پایه‌ی ثابت: اجرای دوباره تکرار نمی‌سازد
F = lambda r: r["fields"]

def find(title_part):
    for i, r in enumerate(rows):
        if title_part in F(r).get("title", ""):
            return i
    raise KeyError(title_part)

# ---------- اصلاح مدخل‌های موجود ----------
i = find("عبدالرحمان")
